import { Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Object} placement
 * @property {(number[]|Object)} placement.position
 * @property {(number[]|Object)} [placement.rotation]
 * @property {(number[]|Object)} [placement.scale]
 * @property {Array<{name:string,params:any}>} [cinematicPrimitives]
 * @property {Object} [atlasRegion]
 * @property {number[]} [atlasRegion.sourceRect] // [x, y, width, height]
 */

/**
 * @typedef {Object} NodeContext
 * @property {function(string):THREE.Texture} textureLoader
 * @property {Object<string,function(THREE.Object3D,any):void>} primitives
 */

/**
 * Create a textured plane node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	// ---------- helpers ----------
	const vecFrom = (value, def = [0, 0, 0]) => {
		if (Array.isArray(value) && value.length === 3) return value;
		if (value && typeof value === 'object') return [value.x ?? 0, value.y ?? 0, value.z ?? 0];
		return def;
	};

	// ---------- geometry ----------
	const sourceRect = config.atlasRegion?.sourceRect ?? [0, 0, 512, 320];
	const texWidth = sourceRect[2];
	const texHeight = sourceRect[3];
	const aspect = texHeight / texWidth;

	const geometry = new PlaneGeometry(1, aspect);

	// ---------- material ----------
	const tex = ctx.textureLoader(config.assets.imageUrl);
	const mat = new MeshBasicNodeMaterial();
	mat.colorNode = texture(tex);
	// allow transparency if the texture has an alpha channel
	mat.transparent = true;

	// ---------- mesh ----------
	const mesh = new Mesh(geometry, mat);

	// ---------- placement ----------
	const pos = vecFrom(config.placement?.position ?? config.position, [0, 0, 0]);
	const rot = vecFrom(config.placement?.rotation ?? config.rotation, [0, 0, 0]);
	const scl = vecFrom(config.placement?.scale ?? config.scale, [1, 1, 1]);

	mesh.position.set(pos[0], pos[1], pos[2]);
	mesh.rotation.set(rot[0], rot[1], rot[2]);
	mesh.scale.set(scl[0], scl[1], scl[2]);

	// ---------- cinematic primitives ----------
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			const fn = ctx.primitives[prim.name];
			if (typeof fn === 'function') {
				fn(mesh, prim.params);
			}
		}
	}

	// ---------- userData ----------
	const timelines = [];

	mesh.userData = {
		handlers: {},
		cleanup: () => {
			geometry.dispose();
			mat.dispose();
			tex?.dispose();
			// kill any GSAP timelines created by this node
			timelines.forEach(t => t.kill());
		},
		// expose a method for node internals to register timelines if needed
		_registerTimeline: (tl) => {
			if (tl && typeof tl.kill === 'function') timelines.push(tl);
		}
	};

	return mesh;
}
